// Utility functions
static inline float gelu_activation(float x) {
    return 0.5f * x * (1.0f + tanhf(0.7978845608f * (x + 0.044715f * x * x * x)));
}

static inline float softmax_stable(float x, float max_val) {
    return expf(x - max_val);
}

